-- A masking policy priority above the `Int64` range used to wrap to a negative value,
-- which was formatted as a query that could not be parsed back.
SELECT formatQueryOrNull('CREATE MASKING POLICY p ON db.t UPDATE x = 1 PRIORITY 9223372036854775807');
SELECT formatQueryOrNull(formatQueryOrNull('CREATE MASKING POLICY p ON db.t UPDATE x = 1 PRIORITY 9223372036854775807')) <=> formatQueryOrNull('CREATE MASKING POLICY p ON db.t UPDATE x = 1 PRIORITY 9223372036854775807');
SELECT formatQueryOrNull('CREATE MASKING POLICY p ON db.t UPDATE x = 1 PRIORITY 9223372036854775808');
SELECT formatQueryOrNull('CREATE MASKING POLICY p ON db.t UPDATE x = 1 PRIORITY 18446744073709551615');
SELECT formatQueryOrNull(formatQueryOrNull('CREATE MASKING POLICY p ON db.t UPDATE x = 1 PRIORITY 18446744073709551615')) <=> formatQueryOrNull('CREATE MASKING POLICY p ON db.t UPDATE x = 1 PRIORITY 18446744073709551615');
CREATE MASKING POLICY p ON db.t UPDATE x = 1 PRIORITY 18446744073709551615; -- { clientError SYNTAX_ERROR }
